/* App switching flows across all 59 reviewed apps, extracted from app store reviews.
 *
 * Generated by pipeline/switching/export_flows.py from the LLM-labeled review pipeline
 * (run_all_switches.py + fix_switching.py): customers only, forced moves from shut-down
 * apps excluded. Static, so the flow overlay works in Demo mode. Node ids match the demo
 * corpus, so a focused cluster's map nodes are also flow nodes.
 *
 * Directions: source -> target means users move (or lean) from source to target.
 * Each monthly row is split by the app whose reviews it was seen in (`o`), because
 * weight_per_10k is normalized by that app's review volume.
 */

import raw from './flows.json' with { type: 'json' };

export type FlowKind = 'switch' | 'return' | 'intent' | 'preference';
/** Visual layers: switches and returns are drawn together. */
export type FlowLayer = 'switch' | 'intent' | 'preference';

export interface FlowNode {
	id: string;
	name: string;
	/** true when we have this app's own reviews */
	observed: boolean;
	/** labeled edges touching this app, all months */
	edgeCount: number;
	volume?: Record<string, number>;
	totalVolume?: number;
	/** switching category from categories.json, e.g. rides_delivery */
	category?: string;
	categoryLabel?: string;
	/** reviewed apps: months missing or below 25% of the app's median volume */
	lowMonths?: string[];
	/** reviewed apps: switching health from app_stats.json */
	health?: FlowHealth;
	healthByPeriod?: Record<string, FlowHealth>;
	volumeNote?: string;
	rating?: { avg: number | null; trend: number | null };
	/** outside apps: reviewed apps whose reviews mention it most */
	seenIn?: string[];
}

/** Balance of switches reported between apps that are both in the dataset (from app_stats.json). */
export interface FlowHealth {
	score: number | null;
	bucket: string | null;
	reportsIn: number | null;
	reportsOut: number | null;
	total: number | null;
}

export interface FlowEdgeRow {
	m: string;
	s: string;
	t: string;
	k: FlowKind;
	/** app whose reviews this was observed in */
	o: string;
	n: number;
	w: number;
	w10k: number;
	/** reasons, most common first */
	r: [string, number][];
}

export interface FlowExample {
	q: string;
	stars: number | null;
	m: string;
	r: string[];
	d: string;
	o: string;
}

export interface FlowMonth {
	month: string;
	full: boolean;
	missing: string[];
	low: string[];
	note: string;
}

export interface FlowReason {
	id: string;
	label: string;
	description: string;
	count: number;
}

export interface FlowAnnotation {
	month: string;
	label: string;
	detail: string;
	/** shown only when the focused cluster contains one of these apps */
	apps?: string[];
}

interface FlowsDataset {
	meta: {
		generatedAt: string;
		model: string;
		edgeRows: number;
		kinds: FlowKind[];
		observed: string[];
		normalization: string;
		window?: string[];
		filters?: string;
		healthDefinition?: string;
		healthBuckets?: Record<string, string>;
	};
	months: FlowMonth[];
	coverage: { start: string; end: string; months: string[]; note: string };
	reasons: FlowReason[];
	nodes: FlowNode[];
	/** compact rows: [month, source, target, kind, observed_in, count, weight, w10k, reason, count, ...] (indexes) */
	edges: { format: string; rows: number[][] } | FlowEdgeRow[];
	examples: Record<string, FlowExample[]>;
	annotations: FlowAnnotation[];
}

const dataset = raw as unknown as FlowsDataset;

function decodeEdges(data: FlowsDataset): FlowEdgeRow[] {
	if (Array.isArray(data.edges)) return data.edges;
	const kinds: FlowKind[] = ['switch', 'return', 'intent', 'preference'];
	const months = data.months.map((m) => m.month);
	const ids = data.nodes.map((n) => n.id);
	const reasons = data.reasons.map((r) => r.id);
	return data.edges.rows.map((row) => {
		const r: [string, number][] = [];
		for (let i = 8; i < row.length; i += 2) r.push([reasons[row[i]], row[i + 1]]);
		return { m: months[row[0]], s: ids[row[1]], t: ids[row[2]], k: kinds[row[3]], o: ids[row[4]],
			n: row[5], w: row[6], w10k: row[7], r };
	});
}

export const flowEdges = decodeEdges(dataset);
export const flows = { ...dataset, edges: flowEdges };

export const flowNodes = flows.nodes;
export const flowMonths = flows.months;
export const allMonthIds = flows.months.map((m) => m.month);
export const coverageMonths = flows.coverage.months;
export const flowAnnotations = flows.annotations;
export const flowReasons = flows.reasons;

const nodeMap = new Map(flowNodes.map((n) => [n.id, n]));
const monthMap = new Map(flowMonths.map((m) => [m.month, m]));
const reasonMap = new Map(flowReasons.map((r) => [r.id, r]));

export function flowNode(id: string): FlowNode | undefined {
	return nodeMap.get(id);
}

export function flowMonth(id: string): FlowMonth | undefined {
	return monthMap.get(id);
}

export function reasonLabel(id: string): string {
	return reasonMap.get(id)?.label ?? id;
}

export function layerOf(kind: FlowKind): FlowLayer {
	return kind === 'return' ? 'switch' : kind;
}

/* ------------------------- reason colours ------------------------- */

/** The most common concrete reasons get their own colour; the rest share grey. */
const REASON_COLOURS: Record<string, string> = {
	price_fees: 'var(--lime)',
	customer_support: 'var(--violet)',
	bugs_performance: 'var(--red)',
	missing_features_limits: 'var(--amber)',
	account_security_trust: 'var(--green)',
	ads: 'var(--pink)',
	content_selection: 'var(--cyan)'
};
export const OTHER_COLOUR = 'var(--muted)';

export const legendReasons = flowReasons
	.filter((r) => r.id in REASON_COLOURS)
	.map((r) => ({ ...r, colour: REASON_COLOURS[r.id] }));

export function reasonColour(id: string | undefined): string {
	return (id && REASON_COLOURS[id]) || OTHER_COLOUR;
}

/* -------------------------- aggregation --------------------------- */

export function volumeOf(appId: string, months: string[]): number {
	const v = nodeMap.get(appId)?.volume;
	if (!v) return 0;
	let sum = 0;
	for (const m of months) sum += v[m] ?? 0;
	return sum;
}

export interface FlowAgg {
	s: string;
	t: string;
	layer: FlowLayer;
	/** weight per 10k reviews of the observing app(s), summed across observing apps */
	value: number;
	count: number;
	weight: number;
	kinds: Partial<Record<FlowKind, number>>;
	reasons: Map<string, number>;
}

export function topReason(reasons: Map<string, number>): string | undefined {
	let best: string | undefined;
	let bestN = 0;
	for (const [id, n] of reasons) {
		// "other" only wins when nothing concrete is stated
		const score = id === 'other' ? n - 0.5 : n;
		if (score > bestN) {
			best = id;
			bestN = score;
		}
	}
	return best;
}

export function sortedReasons(reasons: Map<string, number>): [string, number][] {
	return [...reasons].sort((a, b) => b[1] - a[1]);
}

/**
 * Aggregate edges over a set of months for the visible layers.
 * value = sum over observing apps of (weight / that app's review volume in the period) x 10k.
 * For a single month this equals the exported weight_per_10k.
 */
export function aggregate(months: string[], layers: Set<FlowLayer>, scope: Set<string> | null = null): Map<string, FlowAgg> {
	const monthSet = new Set(months);
	const volumes = new Map<string, number>();
	const out = new Map<string, FlowAgg>();
	for (const row of flowEdges) {
		if (!monthSet.has(row.m)) continue;
		if (scope && !scope.has(row.s) && !scope.has(row.t)) continue;
		const layer = layerOf(row.k);
		if (!layers.has(layer)) continue;
		let vol = volumes.get(row.o);
		if (vol === undefined) {
			vol = volumeOf(row.o, months);
			volumes.set(row.o, vol);
		}
		if (!vol) continue;
		const key = `${row.s}|${row.t}|${layer}`;
		let agg = out.get(key);
		if (!agg) {
			agg = { s: row.s, t: row.t, layer, value: 0, count: 0, weight: 0, kinds: {}, reasons: new Map() };
			out.set(key, agg);
		}
		agg.value += (row.w / vol) * 1e4;
		agg.count += row.n;
		agg.weight += row.w;
		agg.kinds[row.k] = (agg.kinds[row.k] ?? 0) + row.n;
		for (const [id, n] of row.r) agg.reasons.set(id, (agg.reasons.get(id) ?? 0) + n);
	}
	return out;
}

/** Per-month value of one directed pair (all months), summed over the given layers. */
export function pairSeries(s: string, t: string, layers: Set<FlowLayer>): { month: string; value: number; count: number }[] {
	const byMonth = new Map<string, { value: number; count: number }>();
	for (const row of flowEdges) {
		if (row.s !== s || row.t !== t || !layers.has(layerOf(row.k))) continue;
		const cur = byMonth.get(row.m) ?? { value: 0, count: 0 };
		cur.value += row.w10k;
		cur.count += row.n;
		byMonth.set(row.m, cur);
	}
	return allMonthIds.map((month) => ({ month, ...(byMonth.get(month) ?? { value: 0, count: 0 }) }));
}

/** Raw switch + intent counts per month, for the timeline histogram (optionally for a cluster). */
export function monthlyActivityFor(scope: Set<string> | null, pair?: { s: string; t: string }): Record<string, number> {
	const out: Record<string, number> = {};
	for (const row of flowEdges) {
		if (row.k !== 'switch' && row.k !== 'return') continue;
		if (scope && !scope.has(row.s) && !scope.has(row.t)) continue;
		if (pair && (row.s !== pair.s || row.t !== pair.t)) continue;
		out[row.m] = (out[row.m] ?? 0) + row.n;
	}
	return out;
}
export const monthlyActivity = monthlyActivityFor(null);

/* ------------------------ per-cluster coverage ------------------------ */

function observedIn(scope: Set<string> | null): FlowNode[] {
	return flowNodes.filter((n) => n.observed && (!scope || scope.has(n.id)));
}

/** A month is partial for a cluster when one of its reviewed apps is missing or low that month. */
export function monthInfoFor(scope: Set<string> | null, month: string): FlowMonth {
	if (!scope) return flowMonth(month) ?? { month, full: true, missing: [], low: [], note: '' };
	const low = observedIn(scope).filter((n) => n.lowMonths?.includes(month));
	const missing = low.filter((n) => !(n.volume?.[month] ?? 0));
	const thin = low.filter((n) => (n.volume?.[month] ?? 0) > 0);
	const notes: string[] = [];
	if (missing.length) notes.push(`No ${missing.map((n) => n.name).join(', ')} reviews`);
	if (thin.length) notes.push(`Low ${thin.map((n) => n.name).join(', ')} volume`);
	return { month, full: low.length === 0, missing: missing.map((n) => n.id), low: thin.map((n) => n.id), note: notes.join('; ') };
}

/** Longest run of full-coverage months for a cluster (falls back to every month). */
export function coverageFor(scope: Set<string> | null): string[] {
	if (!scope) return coverageMonths;
	let best: string[] = [];
	let run: string[] = [];
	for (const month of allMonthIds) {
		run = monthInfoFor(scope, month).full ? [...run, month] : [];
		if (run.length > best.length) best = run;
	}
	return best.length ? best : allMonthIds;
}

export interface CompetitorRank {
	id: string;
	/** raw switch + return edges with cluster members, all months */
	switches: number;
	/** raw edges of every kind with cluster members, all months (tie-break) */
	total: number;
}

/** Outside apps linked to a cluster, strongest first by raw switch/return counts (all months,
 *  so the ranking and ring positions stay put while the timeline plays). */
export function rankCompetitors(scope: Set<string> | null): CompetitorRank[] {
	if (!scope) return [];
	const ranks = new Map<string, CompetitorRank>();
	for (const row of flowEdges) {
		const sIn = scope.has(row.s);
		const tIn = scope.has(row.t);
		if (sIn === tIn) continue; // inside the cluster, or unrelated to it
		const other = sIn ? row.t : row.s;
		let rank = ranks.get(other);
		if (!rank) {
			rank = { id: other, switches: 0, total: 0 };
			ranks.set(other, rank);
		}
		rank.total += row.n;
		if (row.k === 'switch' || row.k === 'return') rank.switches += row.n;
	}
	return [...ranks.values()].sort((a, b) => b.switches - a.switches || b.total - a.total || a.id.localeCompare(b.id));
}

export function annotationsFor(scope: Set<string> | null): FlowAnnotation[] {
	return flowAnnotations.filter((a) => !scope || a.apps?.some((id) => scope.has(id)));
}

/** Review volume of the distinct observing apps for a route, not a count of users. */
export function pairReviewObservers(s: string, t: string): Set<string> {
	const observers = new Set<string>();
	for (const row of flowEdges) {
		if ((row.s === s && row.t === t) || (row.s === t && row.t === s)) observers.add(row.o);
	}
	if (flowNode(s)?.observed) observers.add(s);
	if (flowNode(t)?.observed) observers.add(t);
	return observers;
}

export function reviewObserversFor(ids: Set<string>): Set<string> {
	const observers = new Set([...ids].filter((id) => flowNode(id)?.observed));
	for (const row of flowEdges) if (ids.has(row.s) || ids.has(row.t)) observers.add(row.o);
	return observers;
}

export function pairReviewVolume(s: string, t: string, months: string[]): number {
	return [...pairReviewObservers(s, t)].reduce((sum, id) => sum + volumeOf(id, months), 0);
}

/** Homepage connections use actual reported switches, never invented similarity edges. */
export function overviewConnections(ids: Set<string>): { s: string; t: string; count: number }[] {
	const pairs = new Map<string, { s: string; t: string; count: number }>();
	for (const row of flowEdges) {
		if ((row.k !== 'switch' && row.k !== 'return') || !ids.has(row.s) || !ids.has(row.t) || row.s === row.t) continue;
		const [s, t] = row.s < row.t ? [row.s, row.t] : [row.t, row.s];
		const key = `${s}|${t}`;
		const pair = pairs.get(key) ?? { s, t, count: 0 };
		pair.count += row.n;
		pairs.set(key, pair);
	}
	const ranked = [...pairs.values()].sort((a, b) => b.count - a.count || a.s.localeCompare(b.s));
	const chosen = new Map<string, typeof ranked[number]>();
	for (const id of ids) {
		for (const pair of ranked.filter((pair) => pair.s === id || pair.t === id).slice(0, 3)) chosen.set(`${pair.s}|${pair.t}`, pair);
	}
	return [...chosen.values()];
}

export function examplesFor(s: string, t: string, kind: FlowKind): FlowExample[] {
	return flows.examples[`${s}|${t}|${kind}`] ?? [];
}

const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function fmtMonth(id: string, short = false): string {
	const [y, m] = id.split('-').map(Number);
	const name = MONTH_NAMES[(m ?? 1) - 1] ?? id;
	return short ? `${name} ’${String(y).slice(2)}` : `${name} ${y}`;
}
